import React, { useState, useEffect } from 'react';
import {
  Card,
  Table,
  Button,
  Modal,
  Form,
  Input,
  Select,
  message,
  Tabs,
  Tag,
  Space,
  Popconfirm,
  Typography,
  Divider,
  Alert,
  Tooltip,
  Badge,
  Switch,
  InputNumber,
} from 'antd';
import {
  UserOutlined,
  CrownOutlined,
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  SafetyOutlined,
  SettingOutlined,
  TeamOutlined,
  KeyOutlined,
  StopOutlined,
  ExclamationCircleOutlined,
} from '@ant-design/icons';
import { usePermissions, PermissionGate } from '../hooks/usePermissions';

const { Title, Text } = Typography;
const { Option } = Select;
const { TabPane } = Tabs;

// Типы данных
interface User {
  user_id: number;
  username: string;
  first_name: string;
  last_name: string;
  roles: string[];
}

interface Role {
  id: number;
  name: string;
  description: string;
  is_system: boolean;
  hierarchy_level?: number;
}

interface Permission {
  id: number;
  key: string;
  description: string;
}

interface RoleLimit {
  id: number;
  role_id: number;
  function_name: string;
  daily_requests?: number;
  monthly_requests?: number;
  max_input_tokens?: number;
  max_output_tokens?: number;
}

const RBACAdmin: React.FC = () => {
  // Состояние данных
  const [users, setUsers] = useState<User[]>([]);
  const [roles, setRoles] = useState<Role[]>([]);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [limits, setLimits] = useState<RoleLimit[]>([]);
  
  // Состояние загрузки
  const [loading, setLoading] = useState(false);
  const [usersLoading, setUsersLoading] = useState(false);
  const [rolesLoading, setRolesLoading] = useState(false);
  
  // Модальные окна
  const [userModalVisible, setUserModalVisible] = useState(false);
  const [roleModalVisible, setRoleModalVisible] = useState(false);
  const [permissionModalVisible, setPermissionModalVisible] = useState(false);
  const [limitModalVisible, setLimitModalVisible] = useState(false);
  
  // Формы
  const [userForm] = Form.useForm();
  const [roleForm] = Form.useForm();
  const [permissionForm] = Form.useForm();
  const [limitForm] = Form.useForm();
  
  // Выбранные элементы
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  
  const { hasRole } = usePermissions();

  // Загрузка данных
  useEffect(() => {
    loadAllData();
  }, []);

  const makeRequest = async (endpoint: string, options: RequestInit = {}) => {
    const telegramId = sessionStorage.getItem('tg_id') || 
      (typeof window !== 'undefined' && (window as any).Telegram?.WebApp?.initDataUnsafe?.user?.id?.toString());
    const token = sessionStorage.getItem('token') || localStorage.getItem('token');
    
    const response = await fetch(endpoint, {
      ...options,
      headers: {
        'X-Telegram-User-ID': telegramId || '',
        'Content-Type': 'application/json',
        ...(token ? { 'Authorization': `Bearer ${token}` } : {}),
        ...options.headers,
      },
    });
    
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`HTTP ${response.status}: ${errorText}`);
    }
    
    return response.json();
  };

  const loadAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        loadUsers(),
        loadRoles(),
        loadPermissions(),
        loadLimits(),
      ]);
    } catch (error) {
      message.error('Ошибка загрузки данных');
      console.error('Load error:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadUsers = async () => {
    try {
      setUsersLoading(true);
      const data = await makeRequest('/api/user-management/users');
      setUsers(data.users || []);
    } catch (error) {
      console.error('Load users error:', error);
    } finally {
      setUsersLoading(false);
    }
  };

  const loadRoles = async () => {
    try {
      setRolesLoading(true);
      const data = await makeRequest('/api/user-management/available-roles');
      setRoles(data.available_roles || []);
    } catch (error) {
      console.error('Load roles error:', error);
    } finally {
      setRolesLoading(false);
    }
  };

  const loadPermissions = async () => {
    try {
      const data = await makeRequest('/api/admin/rbac/permissions');
      setPermissions(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Load permissions error:', error);
    }
  };

  const loadLimits = async () => {
    try {
      const data = await makeRequest('/api/admin/rbac/llm-role-limits');
      setLimits(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Load limits error:', error);
    }
  };

  // Управление ролями пользователей
  const handleAssignRole = async (userId: number, roleName: string) => {
    try {
      await makeRequest('/api/user-management/assign-role', {
        method: 'POST',
        body: JSON.stringify({
          target_user_id: userId,
          role_name: roleName,
        }),
      });
      
      message.success(`Роль "${roleName}" назначена пользователю`);
      await loadUsers();
    } catch (error) {
      message.error(`Ошибка назначения роли: ${error}`);
    }
  };

  const handleRemoveRole = async (userId: number, roleName: string) => {
    try {
      await makeRequest('/api/user-management/remove-role', {
        method: 'POST',
        body: JSON.stringify({
          target_user_id: userId,
          role_name: roleName,
        }),
      });
      
      message.success(`Роль "${roleName}" удалена у пользователя`);
      await loadUsers();
    } catch (error) {
      message.error(`Ошибка удаления роли: ${error}`);
    }
  };

  // Создание новой роли
  const handleCreateRole = async (values: any) => {
    try {
      await makeRequest('/api/admin/rbac/roles', {
        method: 'POST',
        body: JSON.stringify(values),
      });
      
      message.success('Роль успешно создана');
      setRoleModalVisible(false);
      roleForm.resetFields();
      await loadRoles();
    } catch (error) {
      message.error(`Ошибка создания роли: ${error}`);
    }
  };

  // Создание нового права
  const handleCreatePermission = async (values: any) => {
    try {
      await makeRequest('/api/admin/rbac/permissions', {
        method: 'POST',
        body: JSON.stringify(values),
      });
      
      message.success('Право успешно создано');
      setPermissionModalVisible(false);
      permissionForm.resetFields();
      await loadPermissions();
    } catch (error) {
      message.error(`Ошибка создания права: ${error}`);
    }
  };

  // Создание лимита
  const handleCreateLimit = async (values: any) => {
    try {
      await makeRequest('/api/admin/rbac/llm-role-limits', {
        method: 'POST',
        body: JSON.stringify({
          ...values,
          function_name: 'chat',
          priority: 1,
        }),
      });
      
      message.success('Лимит успешно создан');
      setLimitModalVisible(false);
      limitForm.resetFields();
      await loadLimits();
    } catch (error) {
      message.error(`Ошибка создания лимита: ${error}`);
    }
  };

  // Колонки таблицы пользователей
  const userColumns = [
    {
      title: 'Пользователь',
      key: 'user',
      render: (record: User) => (
        <Space>
          <UserOutlined />
          <div>
            <div><strong>{record.first_name} {record.last_name}</strong></div>
            <Text type="secondary">@{record.username || 'N/A'}</Text>
          </div>
        </Space>
      ),
    },
    {
      title: 'ID',
      dataIndex: 'user_id',
      key: 'user_id',
      width: 80,
    },
    {
      title: 'Роли',
      key: 'roles',
      render: (record: User) => (
        <Space wrap>
          {record.roles.map(role => {
            const roleInfo = roles.find(r => r.name === role);
            const color = {
              'architect': 'gold',
              'admin': 'red',
              'vip': 'purple',
              'premium': 'blue',
              'basic': 'default',
            }[role] || 'default';
            
            return (
              <Tag 
                key={role} 
                color={color}
                closable={role !== 'basic'}
                onClose={() => handleRemoveRole(record.user_id, role)}
              >
                {role === 'architect' && <CrownOutlined />} {role}
              </Tag>
            );
          })}
        </Space>
      ),
    },
    {
      title: 'Действия',
      key: 'actions',
      render: (record: User) => (
        <Space>
          <Button
            size="small"
            icon={<PlusOutlined />}
            onClick={() => {
              setSelectedUser(record);
              setUserModalVisible(true);
            }}
          >
            Назначить роль
          </Button>
        </Space>
      ),
    },
  ];

  // Колонки таблицы ролей
  const roleColumns = [
    {
      title: 'Роль',
      key: 'role',
      render: (record: Role) => (
        <Space>
          <SafetyOutlined />
          <div>
            <div><strong>{record.name}</strong></div>
            <Text type="secondary">{record.description}</Text>
          </div>
        </Space>
      ),
    },
    {
      title: 'Уровень',
      dataIndex: 'hierarchy_level',
      key: 'hierarchy_level',
      width: 100,
      render: (level: number) => (
        <Badge count={level} color="blue" />
      ),
    },
    {
      title: 'Системная',
      dataIndex: 'is_system',
      key: 'is_system',
      width: 100,
      render: (isSystem: boolean) => (
        <Tag color={isSystem ? 'red' : 'green'}>
          {isSystem ? 'Да' : 'Нет'}
        </Tag>
      ),
    },
  ];

  // Колонки таблицы прав
  const permissionColumns = [
    {
      title: 'Ключ права',
      dataIndex: 'key',
      key: 'key',
      render: (key: string) => <Text code>{key}</Text>,
    },
    {
      title: 'Описание',
      dataIndex: 'description',
      key: 'description',
    },
  ];

  // Колонки таблицы лимитов
  const limitColumns = [
    {
      title: 'Роль',
      dataIndex: 'role_id',
      key: 'role_id',
      render: (roleId: number) => {
        const role = roles.find(r => r.id === roleId);
        return role ? <Tag color="blue">{role.name}</Tag> : `ID: ${roleId}`;
      },
    },
    {
      title: 'Функция',
      dataIndex: 'function_name',
      key: 'function_name',
    },
    {
      title: 'Дневные запросы',
      dataIndex: 'daily_requests',
      key: 'daily_requests',
      render: (value: number) => value || '∞',
    },
    {
      title: 'Токены вывода',
      dataIndex: 'max_output_tokens',
      key: 'max_output_tokens',
      render: (value: number) => value || '∞',
    },
  ];

  return (
    <div style={{ padding: 'var(--sp-spacing-xl)' }}>
      <div style={{ marginBottom: 'var(--sp-spacing-xl)' }}>
        <Title level={2}>
          <SettingOutlined /> RBAC Администрирование
        </Title>
        <Text type="secondary">
          Управление ролями, правами и лимитами пользователей
        </Text>
      </div>

      <PermissionGate role="architect" fallback={
        <Alert
          message="Доступ запрещен"
          description="Для доступа к RBAC администрированию требуется роль Архитектора"
          type="error"
          icon={<ExclamationCircleOutlined />}
        />
      }>
        <Tabs defaultActiveKey="users" size="large">
          {/* Вкладка пользователей */}
          <TabPane
            tab={
              <span>
                <TeamOutlined />
                Пользователи
              </span>
            }
            key="users"
          >
            <Card>
              <Table
                columns={userColumns}
                dataSource={users}
                rowKey="user_id"
                loading={usersLoading}
                pagination={{ pageSize: 10 }}
              />
            </Card>
          </TabPane>

          {/* Вкладка ролей */}
          <TabPane
            tab={
              <span>
                <CrownOutlined />
                Роли
              </span>
            }
            key="roles"
          >
            <Card
              extra={
                <Button
                  type="primary"
                  icon={<PlusOutlined />}
                  onClick={() => setRoleModalVisible(true)}
                >
                  Создать роль
                </Button>
              }
            >
              <Table
                columns={roleColumns}
                dataSource={roles}
                rowKey="id"
                loading={rolesLoading}
                pagination={{ pageSize: 10 }}
              />
            </Card>
          </TabPane>

          {/* Вкладка прав */}
          <TabPane
            tab={
              <span>
                <KeyOutlined />
                Права
              </span>
            }
            key="permissions"
          >
            <Card
              extra={
                <Button
                  type="primary"
                  icon={<PlusOutlined />}
                  onClick={() => setPermissionModalVisible(true)}
                >
                  Создать право
                </Button>
              }
            >
              <Table
                columns={permissionColumns}
                dataSource={permissions}
                rowKey="id"
                pagination={{ pageSize: 10 }}
              />
            </Card>
          </TabPane>

          {/* Вкладка лимитов */}
          <TabPane
            tab={
              <span>
                <StopOutlined />
                Лимиты
              </span>
            }
            key="limits"
          >
            <Card
              extra={
                <Button
                  type="primary"
                  icon={<PlusOutlined />}
                  onClick={() => setLimitModalVisible(true)}
                >
                  Создать лимит
                </Button>
              }
            >
              <Table
                columns={limitColumns}
                dataSource={limits}
                rowKey="id"
                pagination={{ pageSize: 10 }}
              />
            </Card>
          </TabPane>
        </Tabs>
      </PermissionGate>

      {/* Модальное окно назначения роли */}
      <Modal
        title="Назначить роль пользователю"
        open={userModalVisible}
        onCancel={() => {
          setUserModalVisible(false);
          setSelectedUser(null);
          userForm.resetFields();
        }}
        footer={null}
      >
        <Form
          form={userForm}
          layout="vertical"
          onFinish={(values) => {
            if (selectedUser) {
              handleAssignRole(selectedUser.user_id, values.role_name);
              setUserModalVisible(false);
              userForm.resetFields();
            }
          }}
        >
          <Form.Item label="Пользователь">
            <Input
              value={selectedUser ? `${selectedUser.first_name} ${selectedUser.last_name}` : ''}
              disabled
            />
          </Form.Item>
          
          <Form.Item
            name="role_name"
            label="Роль"
            rules={[{ required: true, message: 'Выберите роль' }]}
          >
            <Select placeholder="Выберите роль">
              {roles.map(role => (
                <Option key={role.name} value={role.name}>
                  {role.name} - {role.description}
                </Option>
              ))}
            </Select>
          </Form.Item>

          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">
                Назначить
              </Button>
              <Button onClick={() => setUserModalVisible(false)}>
                Отмена
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>

      {/* Модальное окно создания роли */}
      <Modal
        title="Создать новую роль"
        open={roleModalVisible}
        onCancel={() => {
          setRoleModalVisible(false);
          roleForm.resetFields();
        }}
        footer={null}
      >
        <Form
          form={roleForm}
          layout="vertical"
          onFinish={handleCreateRole}
        >
          <Form.Item
            name="name"
            label="Название роли"
            rules={[
              { required: true, message: 'Введите название роли' },
              { pattern: /^[a-zA-Z0-9_-]+$/, message: 'Только буквы, цифры, _ и -' }
            ]}
          >
            <Input placeholder="premium_plus" />
          </Form.Item>
          
          <Form.Item
            name="description"
            label="Описание"
            rules={[{ required: true, message: 'Введите описание роли' }]}
          >
            <Input.TextArea placeholder="Описание роли" />
          </Form.Item>

          <Form.Item
            name="is_system"
            label="Системная роль"
            valuePropName="checked"
          >
            <Switch />
          </Form.Item>

          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">
                Создать
              </Button>
              <Button onClick={() => setRoleModalVisible(false)}>
                Отмена
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>

      {/* Модальное окно создания права */}
      <Modal
        title="Создать новое право"
        open={permissionModalVisible}
        onCancel={() => {
          setPermissionModalVisible(false);
          permissionForm.resetFields();
        }}
        footer={null}
      >
        <Form
          form={permissionForm}
          layout="vertical"
          onFinish={handleCreatePermission}
        >
          <Form.Item
            name="key"
            label="Ключ права"
            rules={[
              { required: true, message: 'Введите ключ права' },
              { pattern: /^[a-zA-Z0-9._-]+$/, message: 'Только буквы, цифры, точки, _ и -' }
            ]}
          >
            <Input placeholder="api.feature.read" />
          </Form.Item>
          
          <Form.Item
            name="description"
            label="Описание"
          >
            <Input.TextArea placeholder="Описание права" />
          </Form.Item>

          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">
                Создать
              </Button>
              <Button onClick={() => setPermissionModalVisible(false)}>
                Отмена
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>

      {/* Модальное окно создания лимита */}
      <Modal
        title="Создать лимит для роли"
        open={limitModalVisible}
        onCancel={() => {
          setLimitModalVisible(false);
          limitForm.resetFields();
        }}
        footer={null}
      >
        <Form
          form={limitForm}
          layout="vertical"
          onFinish={handleCreateLimit}
        >
          <Form.Item
            name="role_id"
            label="Роль"
            rules={[{ required: true, message: 'Выберите роль' }]}
          >
            <Select placeholder="Выберите роль">
              {roles.map(role => (
                <Option key={role.id} value={role.id}>
                  {role.name} - {role.description}
                </Option>
              ))}
            </Select>
          </Form.Item>
          
          <Form.Item
            name="daily_requests"
            label="Дневные запросы"
          >
            <InputNumber
              min={1}
              max={10000}
              placeholder="100"
              style={{ width: '100%' }}
            />
          </Form.Item>

          <Form.Item
            name="max_output_tokens"
            label="Максимум токенов вывода"
          >
            <InputNumber
              min={1}
              max={100000}
              placeholder="2048"
              style={{ width: '100%' }}
            />
          </Form.Item>

          <Form.Item>
            <Space>
              <Button type="primary" htmlType="submit">
                Создать
              </Button>
              <Button onClick={() => setLimitModalVisible(false)}>
                Отмена
              </Button>
            </Space>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default RBACAdmin;
